","/* DarkOps Home — Global Styles */

:root {
 --do-surface: rgb(var(--now-color_background--primary, 255, 255, 255));
 --do-surface-elevated: rgb(var(--now-color_background--secondary, 245, 246, 247));
 --do-text: rgb(var(--now-color_text--primary, 16, 23, 26));
 --do-text-muted: rgb(var(--now-color_text--secondary, 75, 85, 89));
 --do-border: rgb(var(--now-container-card--border-color, 207, 213, 215));
 --do-accent: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 --do-radius: var(--now-container-card--border-radius, 8px);
 --do-space-sm: var(--now-static-space--sm, 0.5rem);
 --do-space-md: var(--now-static-space--md, 0.75rem);
 --do-space-lg: var(--now-static-space--lg, 1rem);
 --do-space-xl: var(--now-static-space--xl, 1.5rem);
 --do-space-xxl: var(--now-static-space--xxl, 2rem);
}

* {
 box-sizing: border-box;
}

body {
 margin: 0;
 padding: 0;
 font-family: var(--now-font-family, "Lato", Arial, sans-serif);
 background-color: var(--do-surface);
 color: var(--do-text);
}

.darkops-home {
 min-height: 100vh;
}

/* Hero Header */
.hero {
 background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
 padding: 3rem 2rem;
 text-align: center;
 position: relative;
 overflow: hidden;
}

.hero::before {
 content: "";
 position: absolute;
 top: -50%;
 left: -50%;
 width: 200%;
 height: 200%;
 background: radial-gradient(ellipse at center, rgba(0, 128, 163, 0.08) 0%, transparent 70%);
 pointer-events: none;
}

.hero__content {
 position: relative;
 z-index: 1;
 max-width: 800px;
 margin: 0 auto;
}

.hero__brand {
 display: flex;
 align-items: center;
 justify-content: center;
 gap: var(--do-space-md);
 margin-bottom: var(--do-space-md);
}

.hero__logo {
 font-size: 2.5rem;
 filter: drop-shadow(0 0 12px rgba(0, 128, 163, 0.6));
}

.hero__title {
 margin: 0;
 font-size: 2.75rem;
 font-weight: 800;
 color: #ffffff;
 letter-spacing: -0.02em;
 text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
}

.hero__subtitle {
 margin: var(--do-space-sm) 0 0;
 font-size: 1.15rem;
 color: rgba(255, 255, 255, 0.75);
 font-weight: 400;
 letter-spacing: 0.02em;
}

.hero__greeting {
 margin: var(--do-space-lg) 0 0;
 font-size: 1rem;
 color: rgba(255, 255, 255, 0.55);
}

/* Main Content */
.darkops-main {
 max-width: 1200px;
 margin: 0 auto;
 padding: var(--do-space-xxl) var(--do-space-xl);
}

.section-title {
 margin: 0 0 var(--do-space-lg);
 font-size: 1.25rem;
 font-weight: 700;
 color: var(--do-text);
}

/* KPI Section */
.kpi-section {
 margin-bottom: var(--do-space-xxl);
}

.kpi-grid {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: var(--do-space-lg);
}

@media (max-width: 900px) {
 .kpi-grid {
 grid-template-columns: repeat(2, 1fr);
 }
}

@media (max-width: 500px) {
 .kpi-grid {
 grid-template-columns: 1fr;
 }
}

.kpi-card {
 display: flex;
 flex-direction: column;
 align-items: center;
 padding: var(--do-space-xl) var(--do-space-lg);
 background-color: var(--do-surface-elevated);
 border: 1px solid var(--do-border);
 border-radius: var(--do-radius);
 box-shadow: var(--now-static-drop-shadow--sm);
 transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.kpi-card:hover {
 transform: translateY(-2px);
 box-shadow: var(--now-static-drop-shadow--md);
}

.kpi-card__emoji {
 font-size: 1.75rem;
 margin-bottom: var(--do-space-sm);
}

.kpi-card__value {
 font-size: 2rem;
 font-weight: 800;
 color: var(--do-accent);
 line-height: 1.2;
}

.kpi-card__label {
 margin-top: var(--do-space-sm);
 font-size: 0.8rem;
 font-weight: 600;
 color: var(--do-text-muted);
 text-transform: uppercase;
 letter-spacing: 0.04em;
}

/* Navigation Cards */
.nav-section {
 margin-bottom: var(--do-space-xxl);
}

.nav-grid {
 display: grid;
 grid-template-columns: repeat(2, 1fr);
 gap: var(--do-space-xl);
}

@media (max-width: 768px) {
 .nav-grid {
 grid-template-columns: 1fr;
 }
}

.nav-card {
 display: flex;
 flex-direction: column;
 padding: var(--do-space-xxl) var(--do-space-xl);
 background-color: var(--do-surface-elevated);
 border: 1px solid var(--do-border);
 border-radius: var(--do-radius);
 box-shadow: var(--now-static-drop-shadow--sm);
 transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.nav-card:hover {
 transform: translateY(-3px);
 box-shadow: var(--now-static-drop-shadow--lg);
}

.nav-card__emoji {
 font-size: 2.5rem;
 margin-bottom: var(--do-space-md);
}

.nav-card__title {
 margin: 0 0 var(--do-space-sm);
 font-size: 1.25rem;
 font-weight: 700;
 color: var(--do-text);
}

.nav-card__desc {
 margin: 0 0 var(--do-space-xl);
 font-size: 0.9rem;
 color: var(--do-text-muted);
 line-height: 1.5;
 flex: 1;
}

.nav-card__action {
 margin-top: auto;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
