}","import React, { useState, useEffect } from "react";

const WIN = window as any;
const HEADERS = { "X-UserToken": WIN.g_ck, "Accept": "application/json" };

interface Kpi {
 label: string;
 emoji: string;
 value: string;
}

const KPI_CONFIGS = [
 {
 label: "Open Refunds",
 emoji: "💰",
 url: "/api/now/stats/x_2145749_qc_refund_request?sysparm_query=decisionISEMPTY&sysparm_count=true",
 },
 {
 label: "Store Issues",
 emoji: "🏪",
 url: "/api/now/stats/x_2145749_qc_store_issue?sysparm_query=state=open&sysparm_count=true",
 },
 {
 label: "Partner Incidents",
 emoji: "🤝",
 url: "/api/now/stats/x_2145749_qc_partner_incident?sysparm_query=stateINnew,acknowledged&sysparm_count=true",
 },
 {
 label: "Fraud Flagged",
 emoji: "🚨",
 url: "/api/now/stats/x_2145749_qc_refund_request?sysparm_query=fraud_flagged=true^decisionISEMPTY&sysparm_count=true",
 },
];

export default function KpiCards() {
 const [kpis, setKpis] = useState<Kpi[]>(
 KPI_CONFIGS.map(c => ({ label: c.label, emoji: c.emoji, value: "—" }))
 );

 useEffect(() => {
 KPI_CONFIGS.forEach((cfg, idx) => {
 fetch(cfg.url, { headers: HEADERS })
 .then(r => r.json())
 .then(d => {
 const count = d?.result?.stats?.count ?? "0";
 setKpis(prev => {
 const next = [...prev];
 next[idx] = { ...next[idx], value: count };
 return next;
 });
 })
 .catch(() => {});
 });
 }, []);

 return (
 <section className="kpi-section">
 <h2 className="section-title">Live Operations Pulse</h2>
 <div className="kpi-grid">
 {kpis.map(kpi => (
 <div className="kpi-card" key={kpi.label}>
 <span className="kpi-card__emoji">{kpi.emoji}</span>
 <span className="kpi-card__value">{kpi.value}</span>
 <span className="kpi-card__label">{kpi.label}</span>
 </div>
 ))}
 </div>
 </section>
 );
}
