","import React from "react";
import { Button } from "@servicenow/react-components/Button";

interface DashNav {
 emoji: string;
 title: string;
 description: string;
 url: string;
}

const DASHBOARDS: DashNav[] = [
 {
 emoji: "📊",
 title: "Executive Dashboard",
 description:
 "Strategic overview with revenue, SLA compliance, and operational health metrics",
 url: "x_2145749_qc_exec_dashboard.do",
 },
 {
 emoji: "⚙️",
 title: "Ops Dashboard",
 description:
 "Real-time operational control center for store issues and delivery management",
 url: "x_2145749_qc_ops_dashboard.do",
 },
 {
 emoji: "🛡️",
 title: "Fraud Dashboard",
 description:
 "Fraud detection analytics, risk scoring, and case escalation tracking",
 url: "x_2145749_qc_fraud_dashboard.do",
 },
 {
 emoji: "🏪",
 title: "Dark Store Dashboard",
 description:
 "Store-level performance, pulse scores, and inventory health monitoring",
 url: "x_2145749_qc_dark_store_dashboard.do",
 },
];

function navigateTo(url: string) {
 window.location.assign(url);
}

export default function NavCards() {
 return (
 <section className="nav-section">
 <h2 className="section-title">Command Centers</h2>
 <div className="nav-grid">
 {DASHBOARDS.map(dash => (
 <div className="nav-card" key={dash.title}>
 <span className="nav-card__emoji">{dash.emoji}</span>
 <h3 className="nav-card__title">{dash.title}</h3>
 <p className="nav-card__desc">{dash.description}</p>
 <div className="nav-card__action">
 <Button
 label="Launch"
 variant="primary"
 onClick={() => navigateTo(dash.url)}
 />
 </div>
 </div>
 ))}
 </div>
 </section>
 );
}
","import React, { useState, useEffect } from "react";
import "./app.css";
import HeroHeader from "./components/HeroHeader";
import KpiCards from "./components/KpiCards";
import NavCards from "./components/NavCards";

const WIN = window as any;

function fetchUserName(cb: (name: string) => void) {
 const userName = WIN.NOW?.user?.name || "";
 if (!userName) { cb("Operator"); return; }
 fetch(
 `/api/now/table/sys_user?sysparm_query=user_name=${userName}&sysparm_fields=first_name&sysparm_limit=1`,
 { headers: { "X-UserToken": WIN.g_ck, "Accept": "application/json" } }
 )
 .then(r => r.json())
 .then(d => {
 const first = d?.result?.[0]?.first_name || "Operator";
 cb(first);
 })
 .catch(() => cb("Operator"));
}

export default function App() {
 const [userName, setUserName] = useState("...");

 useEffect(() => { fetchUserName(setUserName); }, []);

 return (
 <div className="darkops-home">
 <HeroHeader userName={userName} />
 <main className="darkops-main">
 <KpiCards />
 <NavCards />
 </main>
 </div>
 );
}
